"""Bounded local cache for remote community preview images.

This module downloads one already-validated preview image for a catalog item,
normalizes it to a small PNG and stores it with a receipt. It is deliberately
not wired into any UI: the trusted catalog resolver supplies the media URL and
the canonical item URL, and the caller decides when to display the returned
local path.

Hard bounds:

- only ``steam_maps`` / ``bakkes_maps`` / ``bakkes_plugins`` sources with a
  canonical numeric id of at most 10 digits;
- ``source_url`` must equal ``community_discovery.item_details_url``;
- the media URL is revalidated with the existing private
  ``community_discovery._thumbnail_url`` helper (imported read-only here, not
  modified), so only the current HTTPS media hosts are reachable;
- at most 2 redirects, each hop revalidated against the same allowlist, and the
  final response URL is checked again before any bytes are trusted;
- 2 MiB response cap, 10 s socket timeout, 15 s monotonic deadline;
- PNG/JPEG only, by signature *and* decoded format, 1..2048 px per side and at
  most 4 megapixels, normalized to PNG at <=480x270 preserving aspect;
- immutable content-addressed images plus an atomic receipt commit point, so a
  failed refresh never removes the previous valid image;
- cache capped at 128 receipts / 32 MiB of actual image bytes, deterministic
  oldest-receipt eviction, and no path from metadata is ever followed.

No cookies, no auth, no SVG, no scripts, no packages, and no game files.
"""

from __future__ import annotations

import hashlib
import json
import math
import os
import re
import stat
import time
import urllib.request
from pathlib import Path
from typing import Callable

from . import community_discovery as _discovery

SOURCES = _discovery.SOURCES

_MAX_BYTES = 2 * 1024 * 1024
_TIMEOUT = 10.0
_DEADLINE = 15.0
_MAX_REDIRECTS = 2
_CHUNK = 64 * 1024
_MAX_SIDE = 2048
_MAX_PIXELS = 4_000_000
_TARGET_W = 480
_TARGET_H = 270
_MAX_ITEMS = 128
_MAX_CACHE_BYTES = 32 * 1024 * 1024
_MAX_CREATOR = 80
_MAX_SOURCE_URL = 400
_MAX_URL = 500
_MAX_RECEIPT = 4096

_ID = re.compile(r"[1-9][0-9]{0,9}")
_KEY = re.compile(r"[0-9a-f]{64}")
_HASH = re.compile(r"[0-9a-f]{64}")
_RECEIPT_NAME = re.compile(r"[0-9a-f]{64}\.json")
_IMAGE_NAME = re.compile(r"[0-9a-f]{64}\.[0-9a-f]{64}\.png")
_TEMP_NAME = re.compile(
    r"\.(?:[0-9a-f]{64}\.json|[0-9a-f]{64}\.[0-9a-f]{64}\.png)\."
    r"[0-9]+\.[0-9]+\.tmp"
)
_MEDIA_TYPES = frozenset({"image/png", "image/jpeg"})
_PNG_MAGIC = b"\x89PNG\r\n\x1a\n"
_JPEG_MAGIC = b"\xff\xd8\xff"
_USER_AGENT = "MyCareerTraining/0.3"
_ACCEPT = "image/png,image/jpeg;q=0.9"


class ThumbnailError(Exception):
    """A preview image could not be validated, downloaded or stored."""


class ThumbnailCancelled(ThumbnailError):
    """The caller cancelled the fetch before it completed."""


def _check(cancel) -> None:
    if cancel is not None and cancel():
        raise ThumbnailCancelled("preview fetch cancelled")


def _bound_text(value, limit: int) -> str:
    if type(value) is not str:
        return ""
    try:
        value.encode("utf-8")
    except UnicodeEncodeError:
        return ""
    text = "".join(" " if (char < " " or char == "\x7f") else char for char in value)
    return " ".join(text.split())[:limit].rstrip()


def _finalized(value) -> float | None:
    if type(value) not in (float, int):
        return None
    try:
        result = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    return result if math.isfinite(result) and result >= 0.0 else None


def _is_reparse(info: os.stat_result) -> bool:
    return bool(getattr(info, "st_file_attributes", 0) & 0x400)


def _signature(data: bytes) -> str | None:
    if data.startswith(_PNG_MAGIC):
        return "png"
    if data.startswith(_JPEG_MAGIC):
        return "jpeg"
    return None


def _to_png(data: bytes) -> bytes:
    """Decode bounded bytes with Qt and re-encode a small PNG."""
    kind = _signature(data)
    if kind is None:
        raise ThumbnailError("preview is not a PNG or JPEG image")
    try:
        from PySide6.QtCore import QBuffer, QByteArray, Qt
        from PySide6.QtGui import QImageReader
    except Exception as exc:  # pragma: no cover - environment failure
        raise ThumbnailError("image decoding is unavailable") from exc

    buffer = QBuffer()
    buffer.setData(QByteArray(data))
    if not buffer.open(QBuffer.ReadOnly):
        raise ThumbnailError("preview could not be opened for decoding")
    try:
        reader = QImageReader(buffer)
        detected = bytes(reader.format()).decode("ascii", "replace").casefold()
        if detected not in ("png", "jpeg"):
            raise ThumbnailError("preview format is not PNG or JPEG")
        if detected != kind:
            raise ThumbnailError("preview signature does not match its format")
        size = reader.size()
        width, height = size.width(), size.height()
        if not (1 <= width <= _MAX_SIDE and 1 <= height <= _MAX_SIDE):
            raise ThumbnailError("preview dimensions are out of bounds")
        if width * height > _MAX_PIXELS:
            raise ThumbnailError("preview pixel count is out of bounds")
        image = reader.read()
        if image.isNull():
            raise ThumbnailError("preview could not be decoded")
        if (image.width(), image.height()) != (width, height):
            raise ThumbnailError("preview decoded size does not match its header")
        if width > _TARGET_W or height > _TARGET_H:
            image = image.scaled(
                _TARGET_W, _TARGET_H,
                Qt.KeepAspectRatio, Qt.SmoothTransformation,
            )
        out = QBuffer()
        if not out.open(QBuffer.WriteOnly):
            raise ThumbnailError("preview could not be re-encoded")
        if not image.save(out, "PNG"):
            raise ThumbnailError("preview could not be re-encoded as PNG")
        return bytes(out.data())
    finally:
        buffer.close()


class _Redirects(urllib.request.HTTPRedirectHandler):
    """Follow at most two redirects, revalidating every hop."""

    max_redirections = _MAX_REDIRECTS

    def __init__(self, source: str):
        self.source = source
        self.hops = 0

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self.hops += 1
        if self.hops > _MAX_REDIRECTS:
            raise ThumbnailError("preview redirected too many times")
        if _discovery._thumbnail_url(self.source, newurl) is None:
            raise ThumbnailError("preview redirected outside the media allowlist")
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def _status(response) -> int:
    value = getattr(response, "status", None)
    if value is None:
        getcode = getattr(response, "getcode", None)
        value = getcode() if callable(getcode) else None
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def _final_url(response, fallback: str) -> str:
    geturl = getattr(response, "geturl", None)
    value = geturl() if callable(geturl) else getattr(response, "url", None)
    return value if type(value) is str and value else fallback


def _content_type(response) -> str:
    headers = getattr(response, "headers", None)
    if headers is None:
        return ""
    try:
        value = headers.get("Content-Type", "")
    except Exception:
        return ""
    return (value or "").split(";")[0].strip().casefold()


class ThumbnailCache:
    """Small, bounded, restart-safe cache of community preview images."""

    def __init__(self, root: Path):
        self.root = Path(os.path.abspath(root))

    # -- public API -------------------------------------------------------- #

    def fetch(
        self,
        source: str,
        source_id: int,
        url: str,
        *,
        creator: str,
        source_url: str,
        opener=None,
        cancel: Callable[[], bool] | None = None,
    ) -> dict:
        key = self._key(source, source_id)
        canonical = self._canonical(source, source_id)
        if source_url != canonical:
            raise ThumbnailError("source_url is not the canonical item URL")
        media = _discovery._thumbnail_url(source, url)
        if media is None:
            raise ThumbnailError("preview URL is not an allowed media URL")
        creator_text = _bound_text(creator, _MAX_CREATOR)
        if not creator_text:
            raise ThumbnailError("preview creator is missing")

        _check(cancel)
        data, final_url = self._download(source, media, opener, cancel)
        png = _to_png(data)
        _check(cancel)

        root = self._root()
        digest = hashlib.sha256(png).hexdigest()
        image_path = self._artifact(f"{key}.{digest}.png")
        receipt_path = self._artifact(f"{key}.json")
        receipt = {
            "source": source,
            "source_id": source_id,
            "path": image_path.name,
            "sha256": digest,
            "creator": creator_text,
            "source_url": canonical,
            "final_url": final_url,
            "bytes": len(png),
            "finalized": time.time(),
        }
        payload = json.dumps(receipt, sort_keys=True).encode("utf-8")
        if len(payload) > _MAX_RECEIPT:
            raise ThumbnailError("preview receipt is too large")

        previous = self._validated_receipt(receipt_path, source, source_id, key)
        image_ready = self._image_equals(image_path, png)
        if not image_ready:
            self._write_atomic(image_path, png)
        try:
            _check(cancel)
            self._write_atomic(receipt_path, payload)
        except BaseException:
            if not image_ready and not (
                previous is not None and previous["path"] == image_path.name
            ):
                self._discard(image_path, root=root)
            raise
        if previous is not None and previous["path"] != image_path.name:
            self._discard(root / previous["path"], root=root)
        self._evict(protect_receipt=receipt_path.name, protect_image=image_path.name)
        return self._result(receipt)

    def lookup(self, source: str, source_id: int) -> dict | None:
        try:
            key = self._key(source, source_id)
            receipt_path = self._artifact(f"{key}.json", create_root=False)
            receipt = self._read_receipt(receipt_path)
            if receipt is None:
                return None
            if not self._valid_receipt(receipt, source, source_id, key):
                return None
            image_path = self._artifact(receipt["path"], create_root=False)
            if not self._plain_file(image_path):
                return None
            if image_path.stat().st_size != receipt["bytes"]:
                return None
            data = image_path.read_bytes()
        except (ThumbnailError, OSError, UnicodeError, ValueError):
            return None
        if len(data) != receipt["bytes"] or len(data) > _MAX_BYTES:
            return None
        if hashlib.sha256(data).hexdigest() != receipt["sha256"]:
            return None
        try:
            _to_png(data)
        except ThumbnailError:
            return None
        return self._result(receipt)

    # -- validation -------------------------------------------------------- #

    def _key(self, source: str, source_id: int) -> str:
        if type(source) is not str or source not in SOURCES:
            raise ThumbnailError("unknown catalog source")
        if type(source_id) is not int or type(source_id) is bool:
            raise ThumbnailError("catalog id must be an integer")
        if _ID.fullmatch(str(source_id)) is None:
            raise ThumbnailError("catalog id is out of bounds")
        return hashlib.sha256(f"{source}:{source_id}".encode("utf-8")).hexdigest()

    def _canonical(self, source: str, source_id: int) -> str:
        try:
            value = _discovery.item_details_url(source, source_id)
        except Exception as exc:
            raise ThumbnailError("canonical item URL is unavailable") from exc
        if type(value) is not str or not value or len(value) > _MAX_SOURCE_URL:
            raise ThumbnailError("canonical item URL is unavailable")
        return value

    def _root(self, *, create: bool = True) -> Path:
        try:
            candidate = Path(os.path.abspath(self.root))
            self._reject_reparse_ancestors(candidate)
            if create:
                candidate.mkdir(parents=True, exist_ok=True)
            elif not candidate.exists():
                raise ThumbnailError("preview cache root is unavailable")
            self._reject_reparse_ancestors(candidate)
            resolved = candidate.resolve(strict=True)
        except ThumbnailError:
            raise
        except OSError as exc:
            raise ThumbnailError("preview cache root is unavailable") from exc
        if not resolved.is_dir():
            raise ThumbnailError("preview cache root is not a directory")
        return resolved

    def _reject_reparse_ancestors(self, path: Path) -> None:
        for ancestor in reversed((path, *path.parents)):
            try:
                info = ancestor.lstat()
            except FileNotFoundError:
                continue
            if stat.S_ISLNK(info.st_mode) or _is_reparse(info):
                raise ThumbnailError("preview cache path contains a link")

    def _artifact(self, name: str, *, create_root: bool = True) -> Path:
        if _RECEIPT_NAME.fullmatch(name) is None and _IMAGE_NAME.fullmatch(name) is None:
            raise ThumbnailError("cache artifact name is not canonical")
        root = self._root(create=create_root)
        path = root / name
        if path.exists() and not self._plain_file(path):
            raise ThumbnailError("cache artifact is a link")
        if path.parent != root:
            raise ThumbnailError("cache artifact escapes the cache root")
        return path

    def _valid_receipt(self, receipt, source: str, source_id: int, key: str) -> bool:
        if type(receipt) is not dict:
            return False
        if set(receipt) != {
            "source", "source_id", "path", "sha256", "creator",
            "source_url", "final_url", "bytes", "finalized",
        }:
            return False
        if receipt["source"] != source:
            return False
        if type(receipt["source_id"]) is not int or receipt["source_id"] != source_id:
            return False
        if type(receipt["creator"]) is not str:
            return False
        creator = _bound_text(receipt["creator"], _MAX_CREATOR)
        if not creator or creator != receipt["creator"]:
            return False
        if len(receipt["creator"].encode("utf-8")) > _MAX_CREATOR * 4:
            return False
        if type(receipt["source_url"]) is not str:
            return False
        if receipt["source_url"] != self._canonical(source, source_id):
            return False
        if type(receipt["final_url"]) is not str:
            return False
        if _discovery._thumbnail_url(source, receipt["final_url"]) is None:
            return False
        digest = receipt["sha256"]
        if type(digest) is not str or _HASH.fullmatch(digest) is None:
            return False
        name = receipt["path"]
        if type(name) is not str or _IMAGE_NAME.fullmatch(name) is None:
            return False
        if name != f"{key}.{digest}.png":
            return False
        size = receipt["bytes"]
        if type(size) is not int or type(size) is bool:
            return False
        if not 0 < size <= _MAX_BYTES:
            return False
        return _finalized(receipt["finalized"]) is not None

    def _validated_receipt(
        self, path: Path, source: str, source_id: int, key: str
    ) -> dict | None:
        receipt = self._read_receipt(path)
        if receipt is None or not self._valid_receipt(receipt, source, source_id, key):
            return None
        return receipt

    def _plain_file(self, path: Path) -> bool:
        try:
            info = path.lstat()
        except OSError:
            return False
        return stat.S_ISREG(info.st_mode) and not _is_reparse(info)

    def _read_receipt(self, path: Path) -> dict | None:
        try:
            if not self._plain_file(path):
                return None
            if path.stat().st_size > _MAX_RECEIPT:
                return None
            with open(path, "rb") as handle:
                raw = handle.read(_MAX_RECEIPT + 1)
        except OSError:
            return None
        if len(raw) > _MAX_RECEIPT:
            return None
        try:
            value = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            return None
        return value if type(value) is dict else None

    # -- network ----------------------------------------------------------- #

    def _download(self, source: str, media: str, opener, cancel) -> tuple[bytes, str]:
        deadline = time.monotonic() + _DEADLINE
        if opener is None:
            opener = urllib.request.build_opener(_Redirects(source))
        request = urllib.request.Request(
            media, headers={"User-Agent": _USER_AGENT, "Accept": _ACCEPT}
        )
        _check(cancel)
        try:
            response = opener.open(request, timeout=_TIMEOUT)
        except ThumbnailError:
            raise
        except Exception as exc:
            raise ThumbnailError("preview download failed") from exc
        try:
            if _status(response) != 200:
                raise ThumbnailError("preview download returned an error status")
            final = _final_url(response, media)
            allowed = _discovery._thumbnail_url(source, final)
            if allowed is None:
                raise ThumbnailError("preview final URL is outside the media allowlist")
            if _content_type(response) not in _MEDIA_TYPES:
                raise ThumbnailError("preview response is not a PNG or JPEG image")
            chunks: list[bytes] = []
            total = 0
            while True:
                _check(cancel)
                if time.monotonic() > deadline:
                    raise ThumbnailError("preview download exceeded its deadline")
                try:
                    chunk = response.read(_CHUNK)
                except Exception as exc:
                    raise ThumbnailError("preview download failed") from exc
                if time.monotonic() > deadline:
                    raise ThumbnailError("preview download exceeded its deadline")
                if not chunk:
                    break
                total += len(chunk)
                if total > _MAX_BYTES:
                    raise ThumbnailError("preview exceeds the size limit")
                chunks.append(chunk)
            if total == 0:
                raise ThumbnailError("preview response was empty")
            return b"".join(chunks), final
        finally:
            close = getattr(response, "close", None)
            if callable(close):
                try:
                    close()
                except Exception:
                    pass

    # -- storage ----------------------------------------------------------- #

    def _write_atomic(self, path: Path, data: bytes) -> None:
        root = self._root()
        if path.parent != root or (path.exists() and not self._plain_file(path)):
            raise ThumbnailError("cache artifact is not a plain file in the cache root")
        temp = root / f".{path.name}.{os.getpid()}.{time.monotonic_ns()}.tmp"
        try:
            descriptor = os.open(
                temp,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0),
                0o600,
            )
        except OSError as exc:
            raise ThumbnailError("preview cache write failed") from exc
        try:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            if not self._plain_file(temp):
                raise ThumbnailError("preview cache temp file is a link")
            os.replace(temp, path)
        except ThumbnailError:
            self._unlink_quietly(temp)
            raise
        except OSError as exc:
            self._unlink_quietly(temp)
            raise ThumbnailError("preview cache write failed") from exc

    def _unlink_quietly(self, path: Path) -> None:
        try:
            if path.is_symlink():
                return
            path.unlink()
        except OSError:
            pass

    def _discard(self, path: Path, *, root: Path | None = None) -> None:
        try:
            root = root or self._root(create=False)
            if path.parent != root or not self._plain_file(path):
                return
            if _IMAGE_NAME.fullmatch(path.name) is None:
                return
            path.unlink()
        except (OSError, ThumbnailError):
            pass

    def _image_equals(self, path: Path, expected: bytes) -> bool:
        try:
            if not self._plain_file(path) or path.stat().st_size != len(expected):
                return False
            return path.read_bytes() == expected
        except OSError:
            return False

    def _result(self, receipt: dict) -> dict:
        return {
            "source": receipt["source"],
            "source_id": receipt["source_id"],
            "path": str(self._root() / receipt["path"]),
            "sha256": receipt["sha256"],
            "creator": receipt["creator"],
            "source_url": receipt["source_url"],
            # Additive: the already validated receipt commit timestamp, so
            # callers can age an entry without trusting file mtimes.
            "finalized": _finalized(receipt["finalized"]),
        }

    def _evict(self, *, protect_receipt: str, protect_image: str) -> None:
        try:
            root = self._root()
            images: dict[str, tuple[Path, int]] = {}
            receipt_paths: list[Path] = []
            for path in root.iterdir():
                if _TEMP_NAME.fullmatch(path.name) is not None:
                    self._unlink_quietly(path)
                    continue
                if not self._plain_file(path):
                    continue
                if _IMAGE_NAME.fullmatch(path.name) is not None:
                    images[path.name] = (path, path.stat().st_size)
                elif _RECEIPT_NAME.fullmatch(path.name) is not None:
                    receipt_paths.append(path)
        except (OSError, ThumbnailError):
            return

        entries = []
        referenced: set[str] = set()
        for receipt_path in receipt_paths:
            receipt = self._read_receipt(receipt_path)
            try:
                source = receipt["source"] if receipt is not None else None
                source_id = receipt["source_id"] if receipt is not None else None
                key = receipt_path.name[:-5]
                valid = (
                    receipt is not None
                    and self._valid_receipt(receipt, source, source_id, key)
                    and receipt["path"] in images
                    and images[receipt["path"]][1] == receipt["bytes"]
                )
            except (ThumbnailError, KeyError, TypeError, UnicodeError, ValueError):
                valid = False
            if not valid:
                if receipt_path.name != protect_receipt:
                    self._unlink_quietly(receipt_path)
                continue
            image, size = images[receipt["path"]]
            referenced.add(receipt["path"])
            entries.append(
                (_finalized(receipt["finalized"]), receipt_path, image, size)
            )

        for name, (image, _size) in tuple(images.items()):
            if name not in referenced and name != protect_image:
                self._discard(image, root=root)
                images.pop(name, None)

        entries.sort(key=lambda item: (item[0], item[1].name))
        total = sum(size for _path, size in images.values())
        count = len(entries)
        for finalized_at, receipt_path, image, size in entries:
            if count <= _MAX_ITEMS and total <= _MAX_CACHE_BYTES:
                break
            if receipt_path.name == protect_receipt:
                continue
            try:
                receipt_path.unlink()
            except OSError:
                continue
            self._discard(image, root=root)
            count -= 1
            total -= size
